@Suite("RandomGraphs Erdős–Rényi exact outputs")
struct ErdosRenyiTests {
    @Test("RG-009 G(10, 0.3) undirected")
    func rg009() {
        // UndirectedAdjacencyList<Int>.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &Xoshiro256StarStar(seed: 0)) → n 10; m 8; E [0–4, 1–2, 1–4, 1–9, 3–4, 3–5, 3–9, 6–9]; draws 9; = NetworkX
        func check(_ graph: some Graph<Int>, _ generator: Xoshiro256StarStar, _ type: String) {
            #expect(graph.vertexCount == 10 && graph.edgeCount == 8 && graph.edges.count == 8, "\(type)")
            #expect(Array(graph.vertices) == Array(0 ..< 10), "\(type)")
            #expect(graph.edges.map { [$0.u, $0.v] } == [[0, 4], [1, 2], [1, 4], [1, 9], [3, 4], [3, 5], [3, 9], [6, 9]] as [[Int]], "\(type)")
            #expect((0 ..< 10).map { graph.degree(of: $0) } == [1, 3, 1, 3, 3, 1, 1, 0, 0, 3] as [Int], "\(type)")
            var expected = Xoshiro256StarStar(seed: 0)
            for _ in 0 ..< 9 { _ = expected.next() }
            #expect(generator == expected, "\(type): 9 draws")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = UndirectedAdjacencyList<Int>.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            check(graph, generator, "UndirectedAdjacencyList<Int>")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = Pseudograph<Int>.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            check(graph, generator, "Pseudograph<Int>")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = Multigraph<Int>.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            check(graph, generator, "Multigraph<Int>")
        }
        // The directed form, from the same model.
        func checkDirected(_ graph: some DirectedGraph<Int>, _ generator: Xoshiro256StarStar, _ type: String) {
            #expect(graph.vertexCount == 10 && graph.edgeCount == 23 && graph.edges.count == 23, "\(type)")
            #expect(Array(graph.vertices) == Array(0 ..< 10), "\(type)")
            #expect(graph.edges.map { [$0.source, $0.target] } == [[0, 4], [1, 2], [1, 4], [1, 9], [3, 4], [3, 5], [3, 9], [4, 1], [4, 2], [4, 3], [5, 0], [5, 3], [6, 0], [6, 1], [6, 5], [6, 9], [7, 0], [7, 3], [7, 4], [7, 6], [8, 1], [8, 3], [8, 6]] as [[Int]], "\(type)")
            #expect((0 ..< 10).map { graph.outDegree(of: $0) } == [1, 3, 0, 3, 3, 2, 4, 4, 3, 0] as [Int], "\(type)")
            var inDegrees = [Int](repeating: 0, count: 10)
            for edge in graph.edges { inDegrees[edge.target] += 1 }
            #expect(inDegrees == [3, 3, 2, 4, 4, 2, 2, 0, 0, 3] as [Int], "\(type)")
            var expected = Xoshiro256StarStar(seed: 0)
            for _ in 0 ..< 25 { _ = expected.next() }
            #expect(generator == expected, "\(type): 25 draws")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = CompressedSparseRow.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            checkDirected(graph, generator, "CompressedSparseRow")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = AdjacencyMatrix.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            checkDirected(graph, generator, "AdjacencyMatrix")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = AdjacencyList<Int>.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            checkDirected(graph, generator, "AdjacencyList<Int>")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = DirectedPseudograph<Int>.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            checkDirected(graph, generator, "DirectedPseudograph<Int>")
        }
        do {
            var generator = Xoshiro256StarStar(seed: 0)
            let graph = DirectedMultigraph<Int>.erdosRenyi(vertexCount: 10, edgeProbability: 0.3, using: &generator)
            checkDirected(graph, generator, "DirectedMultigraph<Int>")
        }
        do {
